/* press-55 EXTERNO — MSE stage-2: media segments (moof/traf/trun families) into configured SB + buffered readback per append. idx-engine fixed (label via explicit name). */
(function(){
"use strict";
if(window.__p55)return; window.__p55=1;
var RID="v55x"+Date.now().toString(36).slice(-13);
function bk(s,b){try{fetch("/beacon/"+s,{method:"POST",cache:"no-store",keepalive:true,headers:{"Content-Type":"application/json"},body:JSON.stringify({r:RID,b:String(b).slice(0,300)})}).catch(function(){});}catch(e){}}
var HB=setInterval(function(){bk("V55-HB","hb");},2000);
bk("V55-L","press55-EXT MSE-stage2 media-segments");
function fmt(e){return String((e&&e.name)||e).slice(0,44);}
try{
  var prev=null;try{prev=JSON.parse(localStorage.getItem("p51-ledger")||"null");}catch(e){}
  var now=Date.now();
  var cur={uid:(prev&&prev.uid)||Math.random().toString(36).slice(2,12),n:((prev&&prev.n)||0)+1,first:(prev&&prev.first)||now,last:now};
  localStorage.setItem("p51-ledger",JSON.stringify(cur));
  var rs=parseInt(localStorage.getItem("p53-restores")||"0",10)+1;
  localStorage.setItem("p53-restores",String(rs));
  bk("V55-Rled","ledger n="+(prev&&prev.n)+"->"+cur.n+" same-uid="+(prev?prev.uid===cur.uid:"n/a")+" restores="+rs);
}catch(e){bk("V55-Rled","ledger-FAIL "+e);}

var P55_INIT = {
  "A-valid": "",
  "B-stsd-entry-lie": "",
  "C-stco-overshoot": "",
  "D-mvhd-ts-zero": "",
  "E-tkhd-wid-huge": ""
};
var P55_SEG = {
  "S1-valid": "",
  "S2-short-mdat": "",
  "S3-extra-sizes": "",
  "S4-zero-dur": "",
  "S5-dur-huge": ""
};

var MIX={};
function bufFrom(s){var raw=atob(s);var a=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a.buffer;}
try{
  for(var k1 in P55_INIT)MIX["I:"+k1]=bufFrom(P55_INIT[k1]);
  for(var k2 in P55_SEG)MIX["S:"+k2]=bufFrom(P55_SEG[k2]);
  bk("V55-Fsz","sizes "+Object.keys(MIX).map(function(k){return k+":"+MIX[k].byteLength;}).join(","));
}catch(e){bk("V55-Fsz","buf-FAIL "+e);}

var vid=null,ms=null,sb=null,opened=false;
var MIME='video/mp4; codecs="avc1.640028"';
var PLAN=[["I:A-valid","init"],["S:S1-valid","seg"],["S:S2-short-mdat","seg"],["S:S3-extra-sizes","seg"],["S:S4-zero-dur","seg"],["S:S5-dur-huge","seg"]];
var pi=0,busy=false,wdog=null,t0=0;

function attach(){
  try{
    vid=document.createElement("video");vid.muted=true;
    if(document.body)document.body.appendChild(vid);
    ms=new MediaSource();
    ms.addEventListener("sourceopen",onOpen);
    vid.src=URL.createObjectURL(ms);
    bk("V55-Fatt","src-attach OK");
  }catch(e){bk("V55-Fatt","attach-EXC "+fmt(e));}
}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",attach);}else{attach();}

function rb(){ /* buffered readback */
  var o="?";
  try{var br=sb.buffered;var parts=[];for(var i=0;i<br.length;i++)parts.push("["+br.start(i).toFixed(0)+"-"+br.end(i).toFixed(0)+"]");o=parts.length?parts.join(","):"EMPTY";var d="";try{d=vid.duration===Infinity?"dur=Inf":"d="+vid.duration.toFixed(1);}catch(e){}return "buffered="+o+" "+d;}catch(e){return "rb-EXC "+fmt(e);}
}
function stepDone(res){
  if(!busy)return;busy=false;if(wdog){clearTimeout(wdog);wdog=null;}
  var ent=PLAN[pi-1];var name=(ent&&ent[0])||("s"+pi);
  bk("V55-R"+name,res+" "+rb());
  pi++;
  if(pi<=PLAN.length)runOne(PLAN[pi-1]);else{try{ms.removeEventListener("sourceopen",onOpen);}catch(e){}bk("V55-END","stage2-done n="+PLAN.length);}
}
function onErr(){stepDone("SB-error");}
function onDone(){stepDone("updateend d="+(performance.now()-t0).toFixed(1)+"ms");}
function runOne(step){
  var name=step[0],kind=step[1];
  busy=true;
  if(!opened){bk("V55-R"+name,"no-open");return;}
  if(kind==="init"){
    if(sb){try{ms.removeSourceBuffer(sb);}catch(e){}sb=null;}
    try{sb=ms.addSourceBuffer(MIME);sb.addEventListener("updateend",onDone);sb.addEventListener("error",onErr);}catch(e){busy=false;bk("V55-R"+name,"sb-EXC "+fmt(e));setTimeout(next2,120);return;}
  }
  t0=performance.now();
  try{
    sb.appendBuffer(MIX[name]);
    bk("V55-E"+name,"sent "+MIX[name].byteLength+"B");
    wdog=setTimeout(function(){stepDone("NO-EVENT-2s");},2000);
  }catch(e){stepDone("append-EXC "+fmt(e));}
}
function next2(){pi++;if(pi<=PLAN.length)runOne(PLAN[pi-1]);else bk("V55-END","early-done");}
function onOpen(){
  if(opened)return;opened=true;
  bk("V55-Ropen","sourceopen readyState="+ms.readyState);
  pi=1;runOne(PLAN[0]);
}
setTimeout(function(){if(!opened){bk("V55-Ropen","sourceopen TIMEOUT 3.2s");}},3400);
setTimeout(function(){clearInterval(HB);bk("V55-Z2","late-z");},22000);
})();
